            ...(episode.top2Ids || []),
            ...(episode.top3Ids || []),
            ...(episode.highIds || []),
            ...(episode.lowIds || []),
            ...(episode.bottomIds || []),
            ...(episode.eliminatedIds || []),
            ...(episode.runOnlyIds || [])
