            eliminatedIds = battle.ids.filter((id) => !survivors.includes(id));
            battle.lipSync.winnerIds = survivors.slice();
            battle.lipSync.winnerId = survivors[0] || null;
            battle.lipSync.loserId = eliminatedIds[0] || null;
            if (decision.resultType === "double_shantay") {
                season.doubleShantaysUsed += 1;
                battle.lipSync.resultType = "double_shantay";
            }
            else if (decision.resultType === "double_sashay") {
                season.doubleSashaysUsed += 1;
                battle.lipSync.resultType = "double_sashay";
            }
