        const colgroup = `<colgroup>${rankCol}${nameCol}${photoCol}${countryCol}${columns.map((col) => `<col class="${String(col.label).toLowerCase() === "finale" ? "track-finale-col" : "track-episode-col"}">`).join("")}<col class="track-ppe-col"></colgroup>`;
