                            id: profile.id,
                            episodesCompeted: profile.episodesCompeted,
                            placementStrength: profile.placementStrength,
                            challengeAvg: profile.challengeAvg,
                            runwayAvg: profile.runwayAvg,
                            challengeTrend: profile.challengeTrend,
